import boto3

def stream_platform_generation(model_id, prompt):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        modelId=model_id,
        body={
            'prompt': prompt,
            'max_tokens': 150
        }
    )
    return response

import boto3

def collect_platform_metadata(response):
    metadata = {
        'usage': response['usageMetadata'],
        'modelId': response['modelId']
    }
    return metadata

import boto3

def get_bedrock_client():
    return boto3.client('bedrock')

class ModelRequest:
    def __init__(self, prompt, max_tokens):
        self.prompt = prompt
        self.max_tokens = max_tokens

class ModelResponse:
    def __init__(self, response):
        self.response = response

    def normalize(self):
        return {
            'output': self.response['outputText'],
            'usage': self.response['usageMetadata']
        }

import boto3

def generate_briefing_audio(output):
    polly = boto3.client('polly')
    response = polly.synthesize_speech(
        Text=output,
        OutputFormat='mp3',
        VoiceId='Joanna'
    )
    return response['AudioStream'].read()
